// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _minSum, uint256 _lockTime, uint256 _putValue, uint256 _collectAm) public {
        // Initialize the contract
        c.SetMinSum(_minSum);
        c.SetLogFile(address(0));
        c.Initialized();

        // Put some ether
        vm.deal(address(this), _putValue);
        c.Put{value: _putValue}(_lockTime);

        // Warp time to allow collect
        vm.warp(block.timestamp + _lockTime + 1);

        // Collect with modified amount to force any MinSum check
        c.Collect(_collectAm);

        // Assert: MinSum should still equal the initial value
        assertTrue(c.MinSum() == _minSum);
    }
