// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _minSumInit, uint256 _lockTime, uint256 _am, uint256 _putVal) public {
        // Bound inputs to avoid overflows or unrealistic values
        _minSumInit = bound(_minSumInit, 0, 1e30);
        _am = bound(_am, 0, 1e30);
        _putVal = bound(_putVal, 0, 1e30);
        _lockTime = bound(_lockTime, 0, 1e10);

        // Set up: initialize, set MinSum, and fund the contract some ETH
        c.SetMinSum(_minSumInit);
        c.Initialized();
        vm.deal(address(c), 1e30); // ensure contract has ETH for potential collect
        vm.deal(address(this), 1e30);

        uint256 minSumBefore = c.MinSum();

        // Perform a sequence that might change MinSum (only possible in buggy version)
        // Since buggy version allows SetMinSum later, we simulate that here for the reference as well (it will revert if called after init)
        // But we only call SetMinSum before Initialized in setup; no further calls to SetMinSum after init.

        // Fund the caller's account to allow Collect
        c.Put{value: _putVal}(_lockTime);

        // Attempt Collect; may revert
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", _am));

        uint256 minSumAfter = c.MinSum();

        // General rule: MinSum never decreases (even if Collect reverts, MinSum unchanged)
        assertTrue(minSumAfter >= minSumBefore);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint constant INITIAL_MINSUM = 100;

    function setUp() public { 
        c = new C(); 
        c.SetMinSum(INITIAL_MINSUM);
        c.SetLogFile(address(123));
        c.Initialized();
    }

    function testFuzz_property(uint256 attackerSum, uint256 lockTime, uint256 am, uint256 money) public {
        // Set up a second account to call Collect
        address attacker = address(0x1234);
        vm.deal(attacker, money);
        vm.prank(attacker);
        c.Put{value: money}(lockTime);

        // Attacker tries to call Collect
        vm.prank(attacker);
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", am));

        // The rule: MinSum must still be the initial value (100) because Initialized() was called, and SetMinSum should revert if called after Initialized
        // In the reference, an attempt to change MinSum after Initialized would revert; in the buggy version, SetMinSum can be called later, but here we don't call SetMinSum again; the rule holds because MinSum hasn't changed.
        // Actually, the difference is that after Initialized, SetMinSum reverts in reference but not in buggy. The test below checks that after a call to SetMinSum after Initialized, MinSum is unchanged in reference but changed in buggy.
        // However, to make the test fail on buggy, we need to call SetMinSum after Initialized and then assert MinSum is unchanged.
        // The fuzz parameters are used to call SetMinSum with a new value, then we check MinSum.
        // Redesign:
        // We call SetMinSum after Initialized with a random new value, then assert MinSum == INITIAL_MINSUM.
        // In reference, the SetMinSum call will revert, so MinSum remains INITIAL_MINSUM.
        // In buggy, SetMinSum succeeds, changing MinSum, so the assertion fails.
        // So we structure:
        //   vm.assume(newMinSum != INITIAL_MINSUM);
        //   try c.SetMinSum(newMinSum) { } catch { }
        //   assertTrue(c.MinSum() == INITIAL_MINSUM);
        uint256 newMinSum = bound(attackerSum, 1, 1e30);
        vm.assume(newMinSum != INITIAL_MINSUM);

        // Call SetMinSum after Initialized – in reference this reverts, in buggy it succeeds
        (bool ok, ) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", newMinSum));
        // The reference reverts; we ignore the return
        // Now check that MinSum equals initial value
        assertTrue(c.MinSum() == INITIAL_MINSUM);
    }
}

