pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { 
        c = new C();
        c.SetMinSum(100);
        c.Initialized();
    }
    function testFuzz_property(uint256 _am, uint256 _lockTime, uint256 _putVal) public {
        vm.assume(_am > 0 && _am <= type(uint256).max - 1e18);
        vm.assume(_lockTime <= type(uint256).max - block.timestamp);
        vm.assume(_putVal >= 100 && _putVal <= type(uint256).max - 1e18);
        vm.deal(address(this), _putVal);
        c.Put{value: _putVal}(_lockTime);
        vm.warp(block.timestamp + _lockTime + 1);
        uint minSumBefore = c.MinSum();
        c.Collect(_am);
        assertTrue(c.MinSum() == minSumBefore);
    }
}

