pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 minSum, uint256 lockTime, uint256 deposit, uint256 collectAmt, bool callSetMinSumAfterInit) public {
        // Bound inputs to avoid overflows
        lockTime = bound(lockTime, 0, 1000000);
        deposit = bound(deposit, 0, 1e18);
        collectAmt = bound(collectAmt, 0, deposit);
        minSum = bound(minSum, 0, 1e18);

        // Setup: deploy and set initial MinSum
        c.SetMinSum(minSum);

        // Fund the test contract with ETH for deposits
        vm.deal(address(this), deposit);

        // Put some ETH into the contract with a lock time
        c.Put{value: deposit}(lockTime);

        // Initialize (lock settings)
        c.Initialized();

        // Optionally call SetMinSum again after initialization (buggy behavior allows change, reference rejects)
        if (callSetMinSumAfterInit) {
            uint256 newMinSum = bound(minSum + 1, 0, 1e18);
            c.SetMinSum(newMinSum);
        }

        // Warp time to ensure lock expires (simulate enough time passing)
        vm.warp(block.timestamp + lockTime + 1);

        // Record MinSum before Collect
        uint256 minSumBefore = c.MinSum();

        // Attempt Collect
        (bool success,) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmt));

        // Read MinSum after Collect
        uint256 minSumAfter = c.MinSum();

        // The general rule: MinSum should never change as a result of Collect
        assertTrue(minSumBefore == minSumAfter, "MinSum changed after Collect");
    }
}

