pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _lockTime, uint256 _val, uint256 _collectAm) public {
        // Bound inputs to reasonable values
        _lockTime = bound(_lockTime, 0, 1000000);
        _val = bound(_val, 0, 1e18);
        _collectAm = bound(_collectAm, 0, 1e18);

        // Fund the test contract to allow Put
        vm.deal(address(this), _val + _collectAm);

        // Drive through Put to accumulate balance
        (bool putOk,) = address(c).call{value: _val}(abi.encodeWithSelector(c.Put.selector, _lockTime));
        if (!putOk) return;

        // Call Collect
        (bool collectOk,) = address(c).call(abi.encodeWithSelector(c.Collect.selector, _collectAm));

        // After the sequence, check that SetMinSum does NOT revert (i.e., the contract is NOT initialized)
        // In reference C, SetMinSum always succeeds because initialised is false (the bug prevents it from being set to true
        // by any public call in this simple sequence). In mutant, if initialised is true, SetMinSum reverts.
        (bool setMinSumOk,) = address(c).call(abi.encodeWithSelector(c.SetMinSum.selector, 0));
        assertTrue(setMinSumOk, "SetMinSum should not revert after any sequence ending with Collect");
    }
}

