pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(
        uint256 lockTime1,
        uint256 value1,
        uint256 lockTime2,
        uint256 value2,
        uint256 collectAm,
        address user
    ) public {
        // Bound and assume reasonable values
        vm.assume(user != address(0));
        lockTime1 = bound(lockTime1, 0, 365 days);
        lockTime2 = bound(lockTime2, 0, 365 days);
        value1 = bound(value1, 0.1 ether, 100 ether);
        value2 = bound(value2, 0.1 ether, 100 ether);
        collectAm = bound(collectAm, 0.1 ether, 10 ether);

        // Record MinSum before any calls
        uint256 minSumBefore = c.MinSum();

        // Perform two Put calls with different users
        vm.deal(user, value1 + value2);
        vm.prank(user);
        c.Put{value: value1}(lockTime1);

        vm.deal(user, value2);
        vm.prank(user);
        c.Put{value: value2}(lockTime2);

        // Warp time to ensure first Put's unlock is reached
        vm.warp(block.timestamp + lockTime1 + 1);

        // Try Collect and check revert status
        vm.prank(user);
        (bool success, ) = address(c).call{value: 0}(
            abi.encodeWithSignature("Collect(uint256)", collectAm)
        );

        if (success) {
            // If Collect succeeded, MinSum should be unchanged
            assertTrue(c.MinSum() == minSumBefore, "MinSum changed after successful Collect");
        }
    }
}

