pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _lockTime, uint256 _putAmount, uint256 _collectAmount, uint256 _minSum) public {
        // Ensure no overflow for Put
        vm.assume(_putAmount <= type(uint256).max - _minSum);
        vm.assume(_collectAmount <= _putAmount); // collect cannot exceed balance
        // Set MinSum first
        c.SetMinSum(_minSum);
        // Fund the contract with enough ether for the put
        vm.deal(address(this), _putAmount);
        // Call Put
        c.Put{value: _putAmount}(_lockTime);
        // Record MinSum before collect
        uint256 minSumBefore = c.MinSum();
        // Warp time to ensure unlock (lockTime is arbitrary, but just to make potential collect possible)
        uint256 unlockTime = block.timestamp + _lockTime;
        if (block.timestamp <= unlockTime) {
            vm.warp(block.timestamp + _lockTime + 1);
        }
        // Try collect
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", _collectAmount));
        // Only assert when collect succeeds (otherwise MinSum could change in buggy version)
        // We want a rule that holds on reference and fails on buggy. 
        // On reference, MinSum never changes. On buggy, if collect succeeds, SetMinSum can be called again? No, bug is in SetMinSum itself:
        // The bug is that SetMinSum can be called after Initialized. So anyone can call SetMinSum at any time.
        // But this test is about Collect: after Collect, we check MinSum unchanged.
        // Actually the bug manifests because SetMinSum can be called after Initialized, changing MinSum. 
        // So the rule: If we don't call SetMinSum between collect and the second check, MinSum should remain same.
        // But the bug allows anyone to call SetMinSum anywhere. So we need to ensure no one calls SetMinSum during test.
        // So we just check that if collect succeeds, MinSum is unchanged from its pre-collect value.
        if (success) {
            uint256 minSumAfter = c.MinSum();
            assertTrue(minSumAfter == minSumBefore, "MinSum changed after successful Collect");
        }
    }
}

