pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address logAddr, uint lockTime, uint putValue, uint collectAmount) public {
        // Bound inputs to reasonable ranges
        lockTime = bound(lockTime, 0, 1000000);
        putValue = bound(putValue, 1, 100 ether);
        collectAmount = bound(collectAmount, 0, putValue);
        vm.assume(logAddr != address(0));

        // Initialize the contract and set minimal sum
        c.SetMinSum(0);
        c.SetLogFile(logAddr);
        c.Initialized();

        // Put some value
        vm.deal(address(this), putValue);
        c.Put{value: putValue}(lockTime);

        // Record LogFile before Collect
        address logBefore = c.LogFile();

