        // Set MinSum to _minSum, but ensure it's not too large to avoid overflow in realistic scenarios
        vm.assume(_minSum <= type(uint256).max / 2);
        // Deploy and initialize
        c.SetMinSum(_minSum);
        c.Initialized();
        // Fund the user and put money
        vm.deal(_user, _putAmount);
        vm.prank(_user);
        c.Put{value: _putAmount}(_lockTime);
        // Now set balance equal to MinSum by adjusting collectAmount to be the balance (we transfer out nothing, but we can use the fact that after Put, balance = _putAmount)
        // We want the case where acc.balance == MinSum. So we need _putAmount == _minSum.
        vm.assume(_putAmount == _minSum);
        // Set collectAmount to be exactly the balance (which equals MinSum)
        uint256 balance = _putAmount; // because we put exactly that amount
        // Ensure collectAmount is exactly balance (to test the edge)
        vm.assume(_collectAmount == balance);
        // Now advance time past unlockTime
        vm.warp(block.timestamp + _lockTime + 1);
        // Call Collect and check it does not revert
        (bool success, ) = address(c).call(
            abi.encodeWithSignature("Collect(uint256)", _collectAmount)
        );
        assertTrue(success, "Collect should succeed when balance == MinSum");
    }
}

