        // Restrict to avoid overflow/underflow issues; we want balance = am = MinSum after setup
        vm.assume(balance >= 1 && balance <= type(uint256).max / 2);
        vm.assume(am == balance); // amount equals balance
        vm.assume(lockTime <= type(uint256).max - block.timestamp);

        // Initialize the contract with MinSum = balance
        c.SetMinSum(balance);
        c.SetLogFile(address(0xdead));
