        // Fund the user and make a deposit with lockTime
        vm.deal(user, balance);
        vm.prank(user);
        c.Put(lockTime);

        // Warp time past unlock
        vm.warp(block.timestamp + lockTime + 1);

        // Now Collect(am) should succeed because balance == MinSum and balance == am and time is past
        vm.prank(user);
        bool success;
        bytes memory result;
        (success, result) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", am));
        assertTrue(success, "Collect should have succeeded when balance equals MinSum");
    }
